const { Client } = require('pg');
const axios = require('axios');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

async function testDatabaseConnection() {
    const client = new Client({
        connectionString: process.env.DATABASE_URL,
    });
    try {
        await client.connect();
        console.log('Database connection successful.');
    } catch (error) {
        console.error('Database connection failed:', error);
    } finally {
        await client.end();
    }
}

async function testApiKeys() {
    try {
        // Example API call for Anthropic
        const anthroResponse = await axios.get('https://api.anthropic.com/v1/health', {
            headers: { 'Authorization': `Bearer ${process.env.ANTHROPIC_API_KEY}` }
        });
        console.log('Anthropic API response:', anthroResponse.data);
    } catch (error) {
        console.error('Anthropic API key validation failed:', error.response ? error.response.data : error.message);
    }

    try {
        // Example API call for Stripe
        const stripeResponse = await axios.get('https://api.stripe.com/v1/health', {
            headers: { 'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}` }
        });
        console.log('Stripe API response:', stripeResponse.data);
    } catch (error) {
        console.error('Stripe API key validation failed:', error.response ? error.response.data : error.message);
    }
}

async function runTests() {
    await testDatabaseConnection();
    await testApiKeys();
}

runTests();
